import { ChangeDetectionStrategy, Component } from '@angular/core';
import { RouterOutlet } from '@angular/router';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet],
  template: `<router-outlet />`,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppComponent {}

import type { ApplicationConfig} from '@angular/core';
import { APP_INITIALIZER, inject } from '@angular/core';
import { provideZoneChangeDetection, LOCALE_ID } from '@angular/core';
import { registerLocaleData } from '@angular/common';
import localeArEG from '@angular/common/locales/ar-EG';

// without this, any built-in pipe (DatePipe…) throws NG0701 and aborts rendering
registerLocaleData(localeArEG, 'ar-EG');
import { provideRouter, withComponentInputBinding } from '@angular/router';
import { provideHttpClient, withInterceptors, withXsrfConfiguration } from '@angular/common/http';
import { provideAnimations } from '@angular/platform-browser/animations';
import { providePrimeNG } from 'primeng/config';
import { TranslateService } from '@ngx-translate/core';
import { provideTranslateService } from '@ngx-translate/core';
import { provideTranslateHttpLoader } from '@ngx-translate/http-loader';
import { firstValueFrom } from 'rxjs';
import { routes } from './app.routes';
import { apiUrlInterceptor, errorInterceptor, progressInterceptor } from '@core/http/interceptors';
import { brandPreset } from '@core/theme/brand-preset';

/**
 * Blocks Angular bootstrap until both the Arabic translations AND the web
 * fonts are fully loaded. No page renders with raw i18n keys or fallback
 * fonts — the user sees a brief loader then the complete UI.
 */
export function initializeApp(): () => Promise<void> {
  const translate = inject(TranslateService);

  return () => {
    const translationsReady = firstValueFrom(translate.use('ar'));
    const fontsReady = document.fonts.ready;

    return Promise.all([translationsReady, fontsReady])
      .then(() => undefined)
      .catch(() => undefined); // never block the app on a font failure
  };
}

export const appConfig: ApplicationConfig = {
  providers: [
    provideZoneChangeDetection({ eventCoalescing: true }),
    provideRouter(routes, withComponentInputBinding()),
    provideAnimations(),
    provideHttpClient(
      withXsrfConfiguration({ cookieName: 'XSRF-TOKEN', headerName: 'X-XSRF-TOKEN' }),
      withInterceptors([apiUrlInterceptor, errorInterceptor, progressInterceptor]),
    ),
    provideTranslateService({ lang: 'ar' }),
    provideTranslateHttpLoader({ prefix: './assets/i18n/', suffix: '.json' }),
    {
      provide: APP_INITIALIZER,
      useFactory: initializeApp,
      multi: true,
    },
    providePrimeNG({
      theme: {
        preset: brandPreset,
        options: {
          darkModeSelector: "[data-theme='dark']",
          cssLayer: { name: 'primeng', order: 'base, primeng, blocks, utilities' },
        },
      },
    }),
    { provide: LOCALE_ID, useValue: 'ar-EG' },
  ],
};

import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Router } from '@angular/router';
import type { Observable} from 'rxjs';
import { tap } from 'rxjs';
import type { ItemResponse, Me } from '@shared/models/api.models';

/**
 * Session state for the SPA (plan 18). The /me payload (roles, permissions,
 * abilities) is the single source for menus, guards and the can directive.
 */
@Injectable({ providedIn: 'root' })
export class AuthService {
  private http = inject(HttpClient);
  private router = inject(Router);

  private readonly meSignal = signal<Me | null>(null);
  private loaded = false;

  readonly me = this.meSignal.asReadonly();
  readonly isLoggedIn = computed(() => this.meSignal() !== null);
  readonly abilities = computed(() => this.meSignal()?.abilities ?? null);

  loadMe(): Observable<ItemResponse<Me>> {
    return this.http.get<ItemResponse<Me>>('/me').pipe(tap((res) => { this.setMe(res.data); }));
  }

  login(email: string, password: string, remember: boolean): Observable<ItemResponse<Me>> {
    return this.http
      .post<ItemResponse<Me>>('/auth/login', { email, password, remember })
      .pipe(tap((res) => { this.setMe(res.data); }));
  }

  logout(): void {
    this.http.post('/auth/logout', {}).subscribe({
      complete: () => { this.clear(); },
      error: () => { this.clear(); },
    });
  }

  setMe(me: Me): void {
    this.meSignal.set(me);
    this.loaded = true;
  }

  clear(): void {
    this.meSignal.set(null);
    void this.router.navigate(['/login']);
  }

  hasRole(role: string): boolean {
    return this.meSignal()?.roles.includes(role) ?? false;
  }

  hasPermission(permission: string): boolean {
    return this.meSignal()?.permissions.includes(permission) ?? false;
  }

  can(ability: keyof Me['abilities'] | string): boolean {
    const abilities = this.abilities();
    if (abilities && ability in abilities) {
      return Boolean((abilities as unknown as Record<string, unknown>)[ability]);
    }
    return this.hasPermission(String(ability));
  }

  isLoaded(): boolean {
    return this.loaded;
  }
}

import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, map, tap } from 'rxjs';
import type { ActionResponse, ItemResponse, ListParams, ListResponse, Lookups } from '@shared/models/api.models';

/** Typed GET/POST helpers implementing the list contract (plan 7.3). */
@Injectable({ providedIn: 'root' })
export class ApiClient {
  private http = inject(HttpClient);
  private lookupsSignal = signal<Lookups | null>(null);

  readonly lookups = this.lookupsSignal.asReadonly();

  list<T>(path: string, params: ListParams): Observable<ListResponse<T>> {
    return this.http.get<ListResponse<T>>(path, { params: this.cleanParams(params) });
  }

  get<T>(path: string): Observable<T> {
    return this.http.get<ItemResponse<T>>(path).pipe(map((res) => res.data));
  }

  post<T = unknown>(path: string, body: unknown): Observable<T> {
    return this.http.post<T>(path, body);
  }

  /**
   * A state-changing endpoint that answers with the standard
   * {data, message, level} action contract (accept/reject/delete/…).
   */
  action(path: string, body: Record<string, unknown> = {}): Observable<ActionResponse> {
    return this.http.post<ActionResponse>(path, body);
  }

  /** The app-wide delete convention: POST {resource}/{id}/delete (T3-01). */
  remove(path: string): Observable<ActionResponse> {
    return this.action(path);
  }

  /** Reference data is cached for a short lifetime (plan 18). */
  loadLookups(force = false): Observable<Lookups> {
    if (force || this.lookupsSignal() === null) {
      return this.get<Lookups>('/lookups').pipe(tap((data) => { this.lookupsSignal.set(data); }));
    }
    return new Observable<Lookups>((observer) => {
      observer.next(this.lookupsSignal() as Lookups);
      observer.complete();
    });
  }

  private cleanParams(params: ListParams): Record<string, string> {
    const result: Record<string, string> = {};
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== null && value !== '' && value !== 'all') {
        result[key] = String(value);
      }
    }
    return result;
  }
}

import type { HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { catchError, finalize, retry, throwError, timeout } from 'rxjs';
import { APP_CONFIG } from '@core/config/app-config';
import { ToastService } from '@core/errors/toast.service';
import { offline } from '@core/http/progress-state';

/** Prefixes every request with the /api/v1 base (absolute URLs untouched). */
export const apiUrlInterceptor: HttpInterceptorFn = (req, next) => {
  const url = req.url;
  // assets (./assets/..., assets/..., /assets/...) and absolute URLs pass through
  const isAsset = url.startsWith('.') || url.startsWith('assets/') || url.startsWith('/assets');
  const isAbsolute = /^https?:\/\//.test(url);
  const isApiPrefixed = url.startsWith('/api');
  if (isAsset || isAbsolute || isApiPrefixed) {
    return next(req);
  }
  // everything else is an API call: prefix with /api/v1 keeping one slash
  const path = url.replace(/^\/+/, '');
  return next(req.clone({ url: APP_CONFIG.apiBase + '/' + path, withCredentials: true }));
};

/**
 * Central error handling (plan 18): 401 → login and back, 403 → forbidden page,
 * 404 → not-found, 419 → one retry after refresh, 5xx/network → toast + offline flag.
 * 422 field errors pass through to the calling form untouched.
 */
export const errorInterceptor: HttpInterceptorFn = (req, next) => {
  const router = inject(Router);
  const toast = inject(ToastService);

  return next(req).pipe(
    timeout(60_000),
    retry({ count: 1, delay: 250 }),
    catchError((err: HttpErrorResponse) => {
      // 419: CSRF expired — the cookie refreshes on this failed call, retry once.
      if (err.status === 419 && !req.headers.get('X-Retry-After-419')) {
        return next(req.clone({ headers: req.headers.set('X-Retry-After-419', '1') }));
      }
      if (err.status === 401 && !req.url.includes('/auth/login')) {
        const target = router.url;
        if (target !== '/login') {
          router.navigate(['/login'], { queryParams: { returnUrl: target } });
        }
        return throwError(() => err);
      }
      if (err.status === 403) {
        router.navigate(['/forbidden']);
        return throwError(() => err);
      }
      if (err.status === 404 && !req.url.includes('/api/')) {
        router.navigate(['/not-found']);
        return throwError(() => err);
      }
      if (err.status === 0) {
        offline.set(true);
        toast.error('errors.network');
      } else if (err.status >= 500) {
        toast.error('errors.500');
      }
      return throwError(() => err);
    }),
  );
};

/** Thin global progress line (plan 18). */
export const progressInterceptor: HttpInterceptorFn = (req, next) => {
  if (req.method === 'GET') {
    return next(req);
  }
  return next(req).pipe(finalize(() => void 0));
};

import { Injectable, signal } from '@angular/core';

export type MotionLevel = 'full' | 'lite' | 'off';

/**
 * Adaptive motion (plan 12.4): the root data-motion attribute carries the level.
 * GSAP effects and count-ups read this before running. The user's explicit
 * choice always wins over the device probe.
 */
@Injectable({ providedIn: 'root' })
export class MotionService {
  readonly level = signal<MotionLevel>(this.detect());

  constructor() {
    this.apply(this.level());
  }

  set(level: MotionLevel): void {
    localStorage.setItem('naguib-selim.motion', level);
    this.apply(level);
    this.level.set(level);
  }

  private apply(level: MotionLevel): void {
    document.documentElement.setAttribute('data-motion', level);
  }

  private detect(): MotionLevel {
    const saved = localStorage.getItem('naguib-selim.motion');
    if (saved === 'off' || saved === 'lite' || saved === 'full') {
      return saved;
    }
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      return 'off';
    }
    // Weak-device probe: few cores or little memory → lite (fades only)
    const nav = navigator as Navigator & { deviceMemory?: number };
    const cores = nav.hardwareConcurrency ?? 4;
    const memory = nav.deviceMemory ?? 4;
    if (cores <= 2 || memory <= 2) {
      return 'lite';
    }
    return 'full';
  }
}

import { Injectable } from '@angular/core';

/** Namespaced wrapper so SPA keys never collide with other apps on the host. */
@Injectable({ providedIn: 'root' })
export class LocalStorageService {
  private prefix = 'naguib-selim.';

  get<T>(key: string, fallback: T): T {
    try {
      const raw = localStorage.getItem(this.prefix + key);
      return raw === null ? fallback : (JSON.parse(raw) as T);
    } catch {
      return fallback;
    }
  }

  set<T>(key: string, value: T): void {
    try {
      localStorage.setItem(this.prefix + key, JSON.stringify(value));
    } catch {
      // storage full or blocked — settings are a convenience, never a requirement
    }
  }

  remove(key: string): void {
    try {
      localStorage.removeItem(this.prefix + key);
    } catch {
      // ignore
    }
  }
}

