        after: this.fmtId(req.expense_category_id),
      });
    }
    if ('expense_item_id' in req) {
      rows.push({
        label: 'direction.picker.item',
        before: this.fmtText(orig.expense_item_name ?? orig.expense_item_id),
        after: this.fmtId(req.expense_item_id),
