export class MyExpensesPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);

  readonly tableKey = 'mine.component';

  readonly columns = [
    { field: 'created_at', header: 'expense.mine.col_date', sortable: true },
    { field: 'amount', header: 'common.amount', sortable: true },
    { field: 'type', header: 'expense.mine.col_type', sortable: true },
    { field: 'description', header: 'expense.mine.col_description', sortable: true }
  ];

  params = signal({ page: 1, per_page: 25, q: '', status: 'all' });

  data = resource<ListResponse<Row>, { page: number; per_page: number; q: string; status: string }>({
    loader: () =>
      firstValueFrom(this.http.get<ListResponse<Row>>('/my-expenses', { params: cleanParams(this.params()) })),
  });

  summaryValue(key: string): string {
    const value = this.data.value()?.meta?.summary?.[key];
    return value === undefined || value === null ? '0' : String(value);
  }

  setParam(key: string, value: string): void {
    this.params.update((p) => ({ ...p, [key]: value, page: 1 }));
    this.data.reload();
  }

  onSearch(term: string): void { this.setParam('q', term); }

  dialogOpen = signal(false);
  sending = signal(false);
  custodies: { id: number; reason: string }[] = [];
  quick = { custody_id: null as number | null, amount: null as number | null, description: '', expense_date: new Date().toISOString().slice(0, 10) };

  constructor() {
    void firstValueFrom(this.http.get<ItemResponse<{ id: number; reason: string }[]>>('/user-custodies')).then((list) => (this.custodies = list.data ?? []));
  }

  submitQuick(): void {
    if (this.quick.custody_id === null || this.quick.amount === null) {
      return;
    }
    this.sending.set(true);
    void firstValueFrom(
      this.http.post<ActionResponse>('/expenses/quick-store', { ...this.quick, is_quick_expense: true }),
    )
      .then((res) => {
        this.sending.set(false);
        this.toast.success(res.message);
        this.dialogOpen.set(false);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.toast.apiError((err as HttpErrorResponse).error?.message ?? 'errors.generic');
      });
  }

  onPage(event: { page: number; per_page: number; sort?: string }): void {
    const current = this.params();
    if (current.page === event.page && current.per_page === event.per_page && (current as { sort?: string }).sort === (event.sort ?? '')) {
      return;
    }
    this.params.update((p) => ({ ...p, page: event.page, per_page: event.per_page , sort: event.sort ?? ''}));
    this.data.reload();
  }
}

function cleanParams(params: Record<string, unknown>): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (value !== null && value !== undefined && value !== '' && value !== 'all') {
      result[key] = String(value);
    }
  }
  return result;
}

