/**
 * Attachment field (plan 11.9, T24): current file with open/replace/remove,
 * type and size validation. Removal in edit requests applies only on approval.
 */
@Component({
  selector: 'app-attachment-field',
  standalone: true,
  imports: [TranslatePipe, ButtonModule, FileUploadModule, FormsModule],
  template: `
    <div class="u-column u-gap-2 u-full">
      @if (current() && !removed()) {
        <div class="attachments__file">
          <svg width="16" height="16" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-paperclip" />
          </svg>
          <span class="attachments__name u-bidi">{{ current() }}</span>
          @if (downloadUrl()) {
            <a [href]="downloadUrl()" target="_blank" rel="noopener">
              {{ 'common.open' | translate }}
            </a>
          }
          @if (canRemove()) {
            <p-button [label]="'common.remove' | translate" size="small" [text]="true" severity="danger" (onClick)="remove.emit()" />
          }
        </div>
      }

      @if (!removed()) {
        <p-fileupload
          mode="basic"
          [customUpload]="true"
          (onSelect)="onSelect($event)"
          [chooseLabel]="current() ? ('common.replace' | translate) : ('common.choose_file' | translate)"
          [auto]="true"
          [maxFileSize]="maxSize()"
        />
        @if (error()) {
          <p class="field__error">{{ error() | translate }}</p>
        }
      }
      @else {
        <p class="field__hint">{{ 'expense.form.attachment_removed' | translate }}</p>
        <p-button [label]="'common.undo' | translate" size="small" [text]="true" (onClick)="removed.set(false)" />
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AttachmentFieldComponent {
  current = input<string | null>(null);
  downloadUrl = input<string | null>(null);
  canRemove = input(true);
  maxSize = input(5_000_000);

  removed = signal(false);
  error = signal('');

  fileChange = output<File | null>();
  remove = output();

  onSelect(event: { files: File[] }): void {
    const file = event.files?.[0];
    if (!file) {
      return;
    }
    if (!['image/jpeg', 'image/png', 'image/webp', 'application/pdf'].includes(file.type)) {
      this.error.set('validation.file_type');
      return;
    }
    this.error.set('');
    this.removed.set(false);
    this.fileChange.emit(file);
  }
}

import type {
  ElementRef,
  OnDestroy} from '@angular/core';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  input,
  signal,
  viewChild,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { ButtonModule } from 'primeng/button';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import { MotionService } from '@core/motion/motion.service';

export interface ChartSeries {
  label: string;
  value: number;
}

/**
 * Titled chart card (plan 16.2). Chart.js loads lazily on the routes that
 * use it. The chart reacts to series() changes — when async data arrives,
 * the chart is created or updated. "View as table" is the a11y version.
 */
@Component({
  selector: 'app-chart-card',
  standalone: true,
  imports: [TranslatePipe, ButtonModule, MoneyPipe],
  template: `
    <div class="chart-card">
      <div class="chart-card__head">
        <span class="chart-card__title">{{ title() | translate }}</span>
        <span class="chart-card__spacer"></span>
        <!-- stopPropagation: the card may sit inside a routerLink wrapper —
             the toggle must switch views in place, never navigate -->
        <p-button
          [label]="(asTable() ? 'common.view_chart' : 'common.view_table') | translate"
          [text]="true"
          size="small"
          (onClick)="toggleView($event)"
        />
      </div>

      <div class="chart-card__body">
        @if (series().length === 0) {
          <p class="u-muted">{{ 'common.no_data' | translate }}</p>
        } @else if (asTable()) {
          <table class="chart-card__table">
            <thead>
              <tr>
                <th scope="col">{{ 'common.name' | translate }}</th>
                <th scope="col">{{ 'common.value' | translate }}</th>
                <th scope="col">%</th>
              </tr>
            </thead>
            <tbody>
              @for (row of tableRows(); track row.label) {
                <tr>
                  <td>{{ row.label }}</td>
                  <td class="u-bidi">{{ row.value | money: false }}</td>
                  <td class="u-bidi">{{ row.percent }}</td>
                </tr>
              }
            </tbody>
          </table>
        } @else {
          <div #host class="u-full" [style.height.px]="height()" style="position: relative;"></div>
        }
      </div>
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ChartCardComponent implements OnDestroy {
  title = input.required<string>();
  series = input.required<ChartSeries[]>();
  height = input(220);
  chartType = input<'doughnut' | 'bar'>('doughnut');

  private motion = inject(MotionService);
  private host = viewChild<ElementRef<HTMLDivElement>>('host');
  readonly asTable = signal(false);

  // fixed series order: brand, light, ink, taupe, mid, sand (plan 10.1.4)
  private readonly palette = ['#5D3722', '#9E877A', '#4F2F1D', '#BEAFA7', '#7D5F4E', '#DFD7D3'];
  private chart: { destroy: () => void; data: { labels: string[]; datasets: { data: number[] }[] } } | null = null;
  private chartLib: (new (
    el: HTMLCanvasElement,
    cfg: Record<string, unknown>,
  ) => { destroy: () => void }) | null = null;

  toggleView(event: Event): void {
    event.stopPropagation();
    event.preventDefault();
    this.asTable.set(!this.asTable());
  }

  tableRows = computed(() => {
    const total = this.series().reduce((sum, s) => sum + s.value, 0);
    return this.series().map((s) => ({
      label: s.label,
      value: s.value,
      percent: total > 0 ? Math.round((s.value / total) * 100) : 0,
    }));
  });

  constructor() {
    // React to series changes: create or update chart when data arrives
    effect(async () => {
      const series = this.series();
      const showTable = this.asTable();

      if (series.length === 0 || showTable) {
        this.destroyChart();
        return;
      }

      // Wait a tick for the #host div to render (it's inside @else)
      await new Promise((r) => setTimeout(r, 0));

      const el = this.host()?.nativeElement;
      if (!el) return;

      await this.renderChart(el, series);
    });
  }

  private async renderChart(el: HTMLDivElement, series: ChartSeries[]): Promise<void> {
    // Load Chart.js once — use /auto which registers all scales and controllers
    if (!this.chartLib) {
      const mod = (await import('chart.js/auto')) as unknown as {
        Chart: new (
          el: HTMLCanvasElement,
          cfg: Record<string, unknown>,
        ) => { destroy: () => void };
      };
      this.chartLib = mod.Chart;
    }

    // Destroy old chart
    this.destroyChart();

    // Clear host and create canvas
    el.innerHTML = '';
    const canvas = document.createElement('canvas');
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    el.appendChild(canvas);

    const labels = series.map((s) => s.label);
    const values = series.map((s) => s.value);
    const colors = series.map((_, i) => this.palette[i % this.palette.length]);
    const surfaceColor =
      getComputedStyle(document.documentElement).getPropertyValue('--color-surface').trim() || '#fff';

    this.chart = new this.chartLib(canvas, {
      type: this.chartType(),
      data: {
        labels,
        datasets: [
          {
            data: values,
            backgroundColor: colors,
            borderColor: surfaceColor,
            borderWidth: 2,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: this.motion.level() === 'full' ? { duration: 350 } : false,
        plugins: {
          legend: {
            display: series.length <= 6,
            position: 'bottom',
            labels: { boxWidth: 10, font: { size: 11 }, color: surfaceColor },
          },
        },
        ...(this.chartType() === 'bar' ? { scales: { y: { beginAtZero: true } } } : {}),
      },
    }) as typeof this.chart;
  }

  private destroyChart(): void {
    if (this.chart) {
      this.chart.destroy();
      this.chart = null;
    }
  }

  ngOnDestroy(): void {
    this.destroyChart();
  }
}

import { ChangeDetectionStrategy, Component, computed, inject, input, output, signal } from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { DialogModule } from 'primeng/dialog';
import { ButtonModule } from 'primeng/button';
import type { HttpErrorResponse } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { ApiClient } from '@core/http/api-client';
import { ToastService } from '@core/errors/toast.service';
import type { ActionResponse, ApiErrorBody } from '@shared/models/api.models';

/**
 * The one delete flow in the app (T3-01): confirm dialog → POST {path} →
 * success toast / server business-rule message via toast.apiError. Pages only
 * react to the `deleted` output (reload the list or navigate back).
 */
@Component({
  selector: 'app-confirm-delete',
  standalone: true,
  imports: [TranslatePipe, DialogModule, ButtonModule],
  template: `
    <p-dialog appendTo="body"
      [visible]="visible()"
      (visibleChange)="visible.set($event)"
      [header]="'common.confirm_delete' | translate"
      [modal]="true"
      [draggable]="false"
      [resizable]="false"
      [closable]="!sending()"
      [style]="{ width: 'min(440px, 94vw)' }"
    >
      <p>{{ 'common.delete_message' | translate: { name: entity() } }}</p>
      @if (alert()) {
        <div class="dialog__alert" role="alert">
          <svg width="16" height="16" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-alert-triangle" />
          </svg>
          <span>{{ alert() }}</span>
        </div>
      }
      <p-footer>
        <div class="u-flex" style="justify-content: flex-end">
          <p-button [label]="'common.cancel' | translate" severity="secondary" [text]="true" [disabled]="sending()" (onClick)="visible.set(false)" />
          <p-button [label]="'common.delete' | translate" severity="danger" [loading]="sending()" (onClick)="confirm()" />
        </div>
      </p-footer>
    </p-dialog>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ConfirmDeleteComponent {
  /** full action path, e.g. `/treasury/3/delete` */
  path = input.required<string>();
  /** display name of the record, interpolated into the message */
  entity = input('');

  deleted = output<ActionResponse>();

  visible = signal(false);
  sending = signal(false);
  private failure = signal<HttpErrorResponse | null>(null);

  private api = inject(ApiClient);
  private toast = inject(ToastService);

  /** server business-rule message shown inside the dialog (public: template) */
  alert = computed(() => {
    const err = this.failure();
    if (!err) {
      return null;
    }
    const body = err.error as ApiErrorBody | null;
    return body?.message ?? null;
  });

  open(): void {
    this.failure.set(null);
    this.visible.set(true);
  }

  confirm(): void {
    this.sending.set(true);
    this.failure.set(null);
    void firstValueFrom(this.api.remove(this.path()))
      .then((res) => {
        this.sending.set(false);
        this.visible.set(false);
        this.toast.success(res.message);
        this.deleted.emit(res);
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.failure.set((err as HttpErrorResponse));
        this.toast.apiError((err as HttpErrorResponse).error?.message ?? 'errors.generic', (err as HttpErrorResponse).error?.code);
      });
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  ElementRef,
  TemplateRef,
  computed,
  contentChild,
  effect,
  inject,
  input,
  output,
  signal,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';
import { ActivatedRoute } from '@angular/router';
import { TableModule } from 'primeng/table';
import { InputTextModule } from 'primeng/inputtext';
import { ButtonModule } from 'primeng/button';
import { LocalStorageService } from '@core/storage/local-storage.service';

export interface TableColumn {
  field: string;
  header: string; // i18n key
  numeric?: boolean;
  width?: string;
  sortable?: boolean;
  /** dot-path used for client-side search when the displayed value is nested (e.g. "agent.name") */
  searchField?: string;
}

export interface TablePageEvent {
  page: number;
  per_page: number;
  sort: string;
  q?: string;
}

/** Per-user table state persisted in localStorage (plan 19.4, 21.2). */
interface TableState {
  columnOrder?: string[];
  columnWidths?: Record<string, string>;
  tableWidth?: string;
  sortField?: string;
  sortDir?: number;
  rows?: number;
}

/** Marks the projected per-row template: <ng-template appTableBody let-row> */
@Directive({ selector: '[appTableBody]' })
export class TableBodyDirective {
  template = inject<TemplateRef<unknown>>(TemplateRef);
}

/**
 * Marks a body <td> with its column field: <td appTableCol="agent">.
 * The cell places itself at the column's saved position on creation and
 * re-places itself when the user reorders columns — so data always moves
 * with its header, on first render AND after row re-creation.
 */
@Directive({ selector: 'td[appTableCol]' })
export class TableColDirective {
  private table = inject(DataTableComponent);
  private el = inject<ElementRef<HTMLTableCellElement>>(ElementRef);

  appTableCol = input.required<string>();

  private placer = effect(() => {
    this.table.placeCell(this.el.nativeElement, this.appTableCol());
  });
}

/**
 * The only table in the app (plan 16.2). Server-side pagination + sorting,
 * ALL columns sortable by default, resizable, reorderable (drag-and-drop),
 * and per-user state (column order, widths, sort, page size) saved to
 * localStorage keyed by the PAGE ROUTE + table key (no collisions between
 * pages that reuse the same component key).
 *
 * Search is client-side: the table filters the rows the parent component
 * provides, matching the query against every column's field value
 * (any value type — string/number/boolean — via dot-path lookup).
 */
@Component({
  selector: 'app-data-table',
  standalone: true,
  imports: [TranslatePipe, TableModule, NgTemplateOutlet, FormsModule, InputTextModule, ButtonModule],
  template: `
    <div class="ledger-table" [class.ledger-table--compact]="density() === 'compact'" [attr.aria-busy]="loading() || null">
      @if (title() !== '' || true) {
        <div class="ledger-table__header">
          @if (title() !== '') {
            <span class="ledger-table__title">{{ title() | translate }}</span>
          }
          <input
            pInputText
            type="search"
            class="ledger-table__filter"
            [placeholder]="'common.search' | translate"
            [attr.aria-label]="'common.search' | translate"
            [ngModel]="searchQuery()" name="searchQuery()"
            (ngModelChange)="onSearch($event)"
          />
          <span class="ledger-table__spacer"></span>
          <button
            type="button"
            class="topbar__icon-btn"
            (click)="toggleDensity()"
            [attr.aria-label]="'common.density' | translate"
            [title]="'common.density' | translate"
          >
            <svg width="16" height="16" aria-hidden="true">
              <use href="assets/icons/sprite.svg#tabler-menu-2" />
            </svg>
          </button>
          <button
            type="button"
            class="topbar__icon-btn"
            (click)="resetState()"
            [attr.aria-label]="'common.reset' | translate"
            [title]="'common.reset' | translate"
          >
            <svg width="16" height="16" aria-hidden="true">
              <use href="assets/icons/sprite.svg#tabler-filter" />
            </svg>
          </button>
          <ng-content select="[toolbar]" />
        </div>
      }

      <p-table
        [value]="filteredRows()"
        [lazy]="true"
        (onLazyLoad)="onLazyLoad($event)"
        (onColReorder)="onColReorder($event)"
        (onColResize)="onColResize($event)"
        [rows]="perPage()"
        [totalRecords]="total()"
        [paginator]="true"
        [rowsPerPageOptions]="[10, 25, 50, 100]"
        [paginatorDropdownAppendTo]="'body'"
        [showCurrentPageReport]="true"
        [currentPageReportTemplate]="'common.table_report' | translate"
        [first]="first()"
        [styleClass]="density() === 'compact' ? 'p-datatable-sm' : ''"
        [resizableColumns]="true"
        [columnResizeMode]="'expand'"
        [reorderableColumns]="true"
        [sortMode]="'single'"
        [sortField]="initialState.sortField || ''"
        [sortOrder]="initialState.sortDir || 1"
        [tableStyle]="tableStyle()"
        [scrollable]="false"
      >
        <ng-template pTemplate="header">
          <tr>
            @for (col of orderedColumns(); track col.field; let i = $index) {
              <th
                [pSortableColumn]="col.sortable === false ? undefined : col.field"
                pResizableColumn
                pReorderableColumn
                [style.width]="columnWidth(col.field)"
                [class.ledger-table__cell-num]="col.numeric"
                [attr.data-field]="col.field"
                scope="col"
                [attr.aria-sort]="ariaSort(col.field)"
              >
                <span class="ledger-table__header-text">{{ col.header | translate }}</span>
                @if (col.sortable !== false) {
                  <p-sortIcon [field]="col.field" />
                }
              </th>
            }
          </tr>
        </ng-template>

        <ng-template pTemplate="body" let-row let-index="rowIndex">
          <ng-container
            [ngTemplateOutlet]="body()?.template ?? null"
            [ngTemplateOutletContext]="{ $implicit: row, index: index, columns: orderedColumns() }"
          />
        </ng-template>

        <ng-template pTemplate="emptymessage">
          <tr>
            <td [colSpan]="orderedColumns().length">
              @if (searchQuery() !== '' && filteredRows().length === 0) {
                <span class="u-muted">{{ 'common.no_results' | translate }}</span>
              } @else {
                <ng-content select="[empty]" />
              }
            </td>
          </tr>
        </ng-template>

        <ng-template pTemplate="loadingbody">
          <tr>
            <td [colSpan]="orderedColumns().length">
              @for (s of [1, 2, 3, 4, 5]; track s) {
                <div class="skeleton skeleton--row"></div>
              }
            </td>
          </tr>
        </ng-template>
      </p-table>

      @if (summaryEntries().length > 0) {
        <div class="ledger-table__summary">
          @for (entry of summaryEntries(); track entry.label) {
            <span>
              {{ entry.label | translate }}:
              <strong class="u-bidi">{{ entry.value }}</strong>
            </span>
          }
        </div>
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DataTableComponent {
  private storage = inject(LocalStorageService);
  private translate = inject(TranslateService);
  private route = inject(ActivatedRoute);
  readonly body = contentChild(TableBodyDirective);

  /** per-component key; the storage key is prefixed with the page route */
  tableKey = input('');
  columns = input.required<TableColumn[]>();
  rows = input.required<unknown[]>();
  total = input(0);
  perPage = input(25);
  first = input(0);
  loading = input(false);
  title = input('');
  summary = input<Record<string, string>>({});

  pageChange = output<TablePageEvent>();

  searchQuery = signal('');
  state = signal<TableState>({});
  density = signal<'comfortable' | 'compact'>(this.storage.get('table.density', 'comfortable'));

  /** page route path (e.g. "users", "custodies/mine") — scopes saved state per page */
  private readonly routePath = this.route.pathFromRoot
    .map((r) => r.routeConfig?.path)
    .filter((p): p is string => !!p && !p.includes(':'))
    .join('/');

  private readonly storageKey = computed(() => {
    const key = this.tableKey() || this.title() || 'table';
    return this.routePath ? `${this.routePath}/${key}` : key;
  });

  private readSavedState(): TableState {
    return this.storage.get<TableState>(`table.state.${this.storageKey()}`, {});
  }

  /**
   * Saved sort restored ONCE — p-table's [sortField]/[sortOrder] inputs are
   * constant after init. Re-binding them on every save made PrimeNG toggle
   * its internal order twice (input feedback), so descending never fired.
   */
  readonly initialState = this.readSavedState();

  constructor() {
    effect(() => {
      const key = this.storageKey();
      const saved = this.storage.get<TableState>(`table.state.${key}`, {});
      this.state.set(saved);

      // seed the first data fetch with the saved sort so header and rows agree
      if (saved.sortField) {
        this.pageChange.emit({
          page: 1,
          per_page: saved.rows ?? 25,
          sort: (saved.sortDir === -1 ? '-' : '') + saved.sortField,
        });
      }
    });
  }

  /**
   * Places a body cell at its column's position (used by TableColDirective).
   * Each cell places ITSELF when created and whenever the saved column order
   * changes — no bulk DOM permutation that could race with PrimeNG's row
   * re-rendering (pagination/sort/filter recreate rows in template order).
   */
  placeCell(td: HTMLTableCellElement, field: string): void {
    const ordered = this.orderedColumns();
    const targetIdx = ordered.findIndex((c) => c.field === field);
    if (targetIdx < 0) return;
    const tr = td.parentElement;
    if (!tr) return;

    const cells = [...tr.children].filter((c) => c.tagName === 'TD');
    const currentIdx = cells.indexOf(td);
    if (currentIdx === -1 || currentIdx === targetIdx) return;

    // moving down needs the slot AFTER the target; moving up lands on it
    const ref = currentIdx < targetIdx ? cells[targetIdx + 1] : cells[targetIdx];
    tr.insertBefore(td, ref ?? null);
  }

  /** rows filtered client-side — matches what the user SEES: raw values,
   *  comma-formatted money, dd/mm/yyyy dates, and translated enum labels */
  filteredRows = computed(() => {
    const q = this.searchQuery().trim().toLowerCase();
    const rows = this.rows();
    if (!q || !Array.isArray(rows)) return rows ?? [];
    const qPlain = q.replace(/,/g, '');
    const fields = this.orderedColumns().map((c) => c.searchField ?? c.field);
    return rows.filter((row) =>
      fields.some((field) => this.cellMatches(this.fieldValue(row, field), q, qPlain)),
    );
  });

  /** one cell's value in every form the interface might display it */
  private cellMatches(value: unknown, q: string, qPlain: string): boolean {
    if (value === null || value === undefined) return false;
    const raw = String(value);
    if (raw.toLowerCase().includes(q)) return true;

    // money: stored "5000.00", displayed "5,000.00"
    if (qPlain && /^-?[\d.]+$/.test(raw) && raw.includes(qPlain)) return true;

    // dates: stored ISO "2026-10-27T…", displayed "27/10/2026"
    const d = /^(\d{4})-(\d{2})-(\d{2})/.exec(raw);
    if (d && `${d[3]}/${d[2]}/${d[1]}`.includes(q)) return true;

    // enums: stored code ("closed"), displayed label ("مغلقة")
    return this.enumLabels(raw).some((label) => label.toLowerCase().includes(q));
  }

  /** every translated label for a value across enum namespaces (cached) */
  private readonly labelCache = new Map<string, string[]>();
  private enumLabels(value: string): string[] {
    const cached = this.labelCache.get(value);
    if (cached) return cached;
    const labels: string[] = [];
    for (const ns of ENUM_NAMESPACES) {
      const key = `enums.${ns}.${value}`;
      const label = this.translate.instant(key);
      if (label && label !== key) labels.push(label);
    }
    this.labelCache.set(value, labels);
    return labels;
  }

  /** dot-path lookup: "agent.name" → row.agent?.name; any value type allowed */
  private fieldValue(row: unknown, field: string): unknown {
    return field.split('.').reduce<unknown>((acc, part) => {
      if (acc !== null && acc !== undefined && typeof acc === 'object') {
        return (acc as Record<string, unknown>)[part];
      }
      return undefined;
    }, row);
  }

  /** Columns reordered + widths restored from saved state */
  orderedColumns = computed(() => {
    const input = this.columns();
    if (!Array.isArray(input) || input.length === 0) return [];
    const cols = [...input];
    const order = this.state().columnOrder;
    if (!order || order.length === 0) return cols;

    const fieldSet = new Set(cols.map((c) => c.field));
    const ordered: TableColumn[] = [];
    for (const field of order) {
      const col = cols.find((c) => c.field === field);
      if (col && fieldSet.has(field)) {
        ordered.push(col);
        fieldSet.delete(field);
      }
    }
    // append any new columns not in the saved order
    for (const col of cols) {
      if (fieldSet.has(col.field)) {
        ordered.push(col);
      }
    }
    return ordered;
  });

  /** aria-sort for the focused column header */
  ariaSort(field: string): 'ascending' | 'descending' | 'none' {
    if (this.state().sortField !== field) return 'none';
    return this.state().sortDir === -1 ? 'descending' : 'ascending';
  }

  columnWidth(field: string): string | null {
    return this.state().columnWidths?.[field] ?? null;
  }

  /** restored table width (expand resize mode grows the table past 100%) */
  tableStyle(): { width: string } | undefined {
    const w = this.state().tableWidth;
    return w ? { width: w } : undefined;
  }

  summaryEntries(): { label: string; value: string }[] {
    return Object.entries(this.summary()).map(([label, value]) => ({ label, value }));
  }

  onSearch(term: string): void {
    // purely client-side: filteredRows recomputes, no server reload
    this.searchQuery.set(term);
  }

  toggleDensity(): void {
    const next = this.density() === 'comfortable' ? 'compact' : 'comfortable';
    this.density.set(next);
    this.storage.set('table.density', next);
  }

  resetState(): void {
    this.storage.remove(`table.state.${this.storageKey()}`);
    this.state.set({});
    this.searchQuery.set('');
  }

  onColReorder(event: { dragIndex?: number | null; dropIndex?: number | null }): void {
    const cols = [...this.orderedColumns()];
    const dragIdx = event.dragIndex ?? 0;
    const dropIdx = event.dropIndex ?? 0;
    const moved = cols.splice(dragIdx, 1)[0];
    cols.splice(dropIdx, 0, moved);
    this.saveState({ columnOrder: cols.map((c) => c.field) });
  }

  onColResize(event: { element?: HTMLElement | null; delta?: number | null }): void {
    const field = event.element?.getAttribute?.('data-field');
    if (!field) return;
    const width = event.element?.style?.width || `${event.element?.offsetWidth || 100}px`;
    // PrimeNG (expand mode) also grew the table element — persist that too,
    // otherwise restored column widths can exceed the 100% container
    const table = event.element?.closest?.('table');
    const tableWidth = table?.style?.width || undefined;
    const widths = { ...(this.state().columnWidths ?? {}), [field]: width };
    this.saveState({ columnWidths: widths, ...(tableWidth ? { tableWidth } : {}) });
  }

  onLazyLoad(event: {
    first?: number | null;
    rows?: number | null;
    sortField?: string | string[] | null;
    sortOrder?: number | null;
  }): void {
    const first = event.first ?? 0;
    const rows = event.rows ?? 25;
    const sortField = Array.isArray(event.sortField) ? event.sortField[0] : event.sortField;
    let sort = '';
    if (sortField) {
      sort = (event.sortOrder === -1 ? '-' : '') + sortField;
    }

    // persist sort + page size
    this.saveState({
      sortField: sortField || '',
      sortDir: event.sortOrder ?? 0,
      rows,
    });

    this.pageChange.emit({
      page: Math.floor(first / Math.max(rows, 1)) + 1,
      per_page: rows,
      sort,
    });
  }

  private saveState(partial: Partial<TableState>): void {
    const current = this.state();
    const next = { ...current, ...partial };
    this.state.set(next);
    this.storage.set(`table.state.${this.storageKey()}`, next);
  }
}

/** enum namespaces used across the app — for search label matching */
const ENUM_NAMESPACES = [
  'custody_status', 'transfer_status', 'return_request', 'review_state', 'social_case',
  'purchase_request', 'maintenance_request', 'task', 'salary', 'edit_request',
  'broadcast', 'transaction_type', 'expense_type', 'priority',
] as const;

import { ChangeDetectionStrategy, Component, computed, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { SelectModule } from 'primeng/select';
import type { DirectionItem, DirectionNode } from '@shared/models/api.models';

export interface DirectionSelection {
  category_id: number | null;
  item_id: number | null;
  /** true only when a final item is chosen (mandatory to the last level, T30) */
  complete: boolean;
}

/**
 * Cascading four-level direction picker (plan 11.6, T30/T31). Selection is
 * mandatory down to the last level (the item). Emits on every level change.
 */
@Component({
  selector: 'app-direction-picker',
  standalone: true,
  imports: [TranslatePipe, SelectModule, FormsModule],
  template: `
    <div class="u-column u-gap-2 u-full" role="group" [attr.aria-label]="'direction.picker.group' | translate">
      <div>
        <label class="field__label" [for]="idBase + '-l1'">
          {{ 'direction.picker.level_1' | translate }} <span class="field__required" aria-hidden="true">*</span>
        </label>
        <p-select appendTo="body"
          [inputId]="idBase + '-l1'"
          [options]="level1()"
          optionLabel="name"
          optionValue="id"
          [(ngModel)]="selected1" name="selected1"
          (ngModelChange)="onLevel1()"
          [placeholder]="'common.choose' | translate"
          styleClass="u-full"
          [autofocus]="false"
        />
      </div>

      @if (level2().length) {
        <div>
          <label class="field__label" [for]="idBase + '-l2'">
            {{ 'direction.picker.level_2' | translate }}
          </label>
          <p-select appendTo="body"
            [inputId]="idBase + '-l2'"
            [options]="level2()"
            optionLabel="name"
            optionValue="id"
            [(ngModel)]="selected2" name="selected2"
            (ngModelChange)="onLevel2()"
            [placeholder]="'common.choose' | translate"
            styleClass="u-full"
          />
        </div>
      }

      @if (level3().length) {
        <div>
          <label class="field__label" [for]="idBase + '-l3'">
            {{ 'direction.picker.level_3' | translate }}
          </label>
          <p-select appendTo="body"
            [inputId]="idBase + '-l3'"
            [options]="level3()"
            optionLabel="name"
            optionValue="id"
            [(ngModel)]="selected3" name="selected3"
            (ngModelChange)="onLevel3()"
            [placeholder]="'common.choose' | translate"
            styleClass="u-full"
          />
        </div>
      }

      @if (items().length) {
        <div>
          <label class="field__label" [for]="idBase + '-item'">
            {{ 'direction.picker.item' | translate }} <span class="field__required" aria-hidden="true">*</span>
          </label>
          <p-select appendTo="body"
            [inputId]="idBase + '-item'"
            [options]="items()"
            optionLabel="name"
            optionValue="id"
            [(ngModel)]="selectedItem" name="selectedItem"
            (ngModelChange)="emit()"
            [placeholder]="'common.choose' | translate"
            styleClass="u-full"
          />
          @if (selectedItem() && defaultAmount() !== null) {
            <p class="field__hint u-bidi">{{ 'direction.picker.default_amount' | translate }}: {{ defaultAmount() }}</p>
          }
        </div>
      }

      @if (touched() && !complete()) {
        <p class="field__error">
          {{ 'direction.picker.incomplete' | translate }}
        </p>
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DirectionPickerComponent {
  tree = input.required<DirectionNode[]>();
  idBase = input('dir');
  required = input(true);

  selectionChange = output<DirectionSelection>();

  selected1 = signal<number | null>(null);
  selected2 = signal<number | null>(null);
  selected3 = signal<number | null>(null);
  selectedItem = signal<number | null>(null);
  touched = signal(false);

  private counter = 0;
  readonly uid = `dir-${++DirectionPickerComponent.prototype.counter}-${Math.floor(Math.random() * 10000)}`;

  level1 = computed<DirectionNode[]>(() => this.tree());
  level2 = computed<DirectionNode[]>(() => this.find(this.selected1())?.children ?? []);
  level3 = computed<DirectionNode[]>(() => this.find(this.selected2())?.children ?? []);
  items = computed<DirectionItem[]>(() => {
    const node = this.find(this.selected3()) ?? this.find(this.selected2());
    return node?.items ?? [];
  });

  defaultAmount = computed<string | null>(() => {
    const item = this.items().find((i) => i.id === this.selectedItem());
    return item?.default_amount ?? null;
  });

  complete = computed(() => this.selectedItem() !== null);

  private find(id: number | null): DirectionNode | undefined {
    if (id === null) {
      return undefined;
    }
    const walk = (nodes: DirectionNode[]): DirectionNode | undefined => {
      for (const node of nodes) {
        if (node.id === id) {
          return node;
        }
        const child = walk(node.children);
        if (child) {
          return child;
        }
      }
      return undefined;
    };
    return walk(this.tree());
  }

  /**
   * Restore a saved selection (edit mode): resolves the ancestor chain of the
   * category from the tree and selects the item — no selectionChange emission,
   * the form already knows the saved direction.
   */
  seed(categoryId: number | null, itemId: number | null): void {
    if (categoryId === null) {
      return;
    }
    const path = this.findPath(categoryId);
    if (!path || path.length === 0) {
      return;
    }
    this.selected1.set(path[0] ?? null);
    this.selected2.set(path[1] ?? null);
    this.selected3.set(path[2] ?? null);
    this.selectedItem.set(itemId);
  }

  private findPath(id: number, nodes: DirectionNode[] = this.tree(), acc: number[] = []): number[] | null {
    for (const node of nodes) {
      const next = [...acc, node.id];
      if (node.id === id) {
        return next;
      }
      const found = this.findPath(id, node.children, next);
      if (found) {
        return found;
      }
    }
    return null;
  }

  onLevel1(): void {
    this.selected2.set(null);
    this.selected3.set(null);
    this.selectedItem.set(null);
    this.touched.set(true);
    this.emit();
  }

  onLevel2(): void {
    this.selected3.set(null);
    this.selectedItem.set(null);
    this.touched.set(true);
    this.emit();
  }

  onLevel3(): void {
    this.selectedItem.set(null);
    this.touched.set(true);
    this.emit();
  }

  /** Preset the picker from saved ids (edit forms). */
  preset(categoryId: number | null, itemId: number | null): void {
    const node = categoryId !== null ? this.find(categoryId) : undefined;
    if (!node) {
      return;
    }
    // level 1..3 chain to the node holding the item
    this.selected1.set(node.level === 1 ? node.id : this.ancestorAt(node, 1)?.id ?? node.id);
    this.selected2.set(node.level === 2 ? node.id : this.ancestorAt(node, 2)?.id ?? null);
    this.selected3.set(node.level === 3 ? node.id : null);
    this.selectedItem.set(itemId);
  }

  private ancestorAt(node: DirectionNode, level: number): DirectionNode | null {
    const walk = (nodes: DirectionNode[], depth: number): DirectionNode | null => {
      for (const candidate of nodes) {
        if (candidate.level === level && this.isAncestor(candidate, node)) {
          return candidate;
        }
        const found = walk(candidate.children, depth);
        if (found) {
          return found;
        }
      }
      return null;
    };
    return walk(this.tree(), level);
  }

  private isAncestor(candidate: DirectionNode, node: DirectionNode): boolean {
    const walk = (nodes: DirectionNode[]): boolean =>
      nodes.some((n) => n.id === node.id || walk(n.children));
    return walk(candidate.children);
  }

  emit(): void {
    this.selectionChange.emit({
      category_id: this.selected2() ?? this.selected3() ?? this.selected1(),
      item_id: this.selectedItem(),
      complete: this.complete(),
    });
  }
}

import { ChangeDetectionStrategy, Component, computed, input, model, output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { DialogModule } from 'primeng/dialog';
import { ButtonModule } from 'primeng/button';
import type { HttpErrorResponse } from '@angular/common/http';
import type { ApiErrorBody } from '@shared/models/api.models';

/**
 * One pattern for every modal form (plan 11.14): inline field errors stay in
 * the page form; this host shows the general alert, keeps values on error,
 * and disables submit while sending (T25).
 */
@Component({
  selector: 'app-form-dialog',
  standalone: true,
  imports: [TranslatePipe, DialogModule, ButtonModule, FormsModule],
  template: `
    <p-dialog appendTo="body"
      [visible]="visible()"
      (visibleChange)="visible.set($event)"
      [header]="header() | translate"
      [modal]="true"
      [draggable]="false"
      [resizable]="false"
      styleClass="dialog"
      [breakpoints]="{ '576px': '100vw' }"
      [style]="{ width: 'min(560px, 94vw)' }"
      [closable]="!sending()"
    >
      <ng-content />
      @if (alert()) {
        <div class="dialog__alert" role="alert">
          <svg width="16" height="16" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-alert-triangle" />
          </svg>
          <span>{{ alert() }}</span>
        </div>
      }
      <p-footer>
        <div class="u-flex u-gap-2" style="justify-content: flex-end">
          <p-button
            [label]="'common.cancel' | translate"
            severity="secondary"
            [text]="true"
            (onClick)="cancel()"
            [disabled]="sending()"
          />
          <p-button
            [label]="submitLabel() | translate"
            (onClick)="submit.emit()"
            [loading]="sending()"
            [disabled]="sending()"
          />
        </div>
      </p-footer>
    </p-dialog>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class FormDialogComponent {
  header = input.required<string>();
  submitLabel = input('common.save');
  sending = input(false);
  error = input<HttpErrorResponse | null>(null);

  visible = model(false);
  submit = output();
  closed = output();

  alert = computed(() => {
    const err = this.error();
    if (!err) {
      return null;
    }
    const body = err.error as ApiErrorBody | null;
    return body?.message ?? null;
  });

  open(): void {
    this.visible.set(true);
  }

  close(): void {
    this.visible.set(false);
    this.closed.emit();
  }

  cancel(): void {
    this.close();
  }
}

import { ChangeDetectionStrategy, Component, computed, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { DecimalPipe } from '@angular/common';
import { TranslatePipe } from '@ngx-translate/core';
import { ButtonModule } from 'primeng/button';
import { InputNumberModule } from 'primeng/inputnumber';
import { InputTextModule } from 'primeng/inputtext';
import { IconComponent } from '@shared/ui/icon/icon.component';

export interface LineItem {
  description: string;
  quantity: number;
  unit_price: number;
}

/**
 * Line items editor (plan 11.10, T4/T5/D3): rows with a running total and a
 * NON-BLOCKING warning when the total differs from the expense amount.
 */
@Component({
  selector: 'app-line-items-editor',
  standalone: true,
  imports: [DecimalPipe, TranslatePipe, FormsModule, ButtonModule, InputTextModule, InputNumberModule, IconComponent],
  template: `
    <div class="u-column u-gap-2 u-full">
      @for (item of items(); track $index; let i = $index) {
        <div class="line-items__row">
          <input
            pInputText
            type="text"
            [(ngModel)]="item.description" [name]="'li-desc-' + i"
            (ngModelChange)="change()"
            [placeholder]="'expense.form.line_items.description' | translate"
            [attr.aria-label]="'expense.form.line_items.description' | translate"
          />
          <p-inputnumber
            [(ngModel)]="item.quantity" [name]="'li-qty-' + i"
            (ngModelChange)="change()"
            [min]="1"
            [showButtons]="true"
            [attr.aria-label]="'expense.form.line_items.quantity' | translate"
            size="small"
          />
          <div class="line-items__cell-price">
            <p-inputnumber
              [(ngModel)]="item.unit_price" [name]="'li-price-' + i"
              (ngModelChange)="change()"
              [minFractionDigits]="2"
              [maxFractionDigits]="2"
              [min]="0"
              mode="decimal"
              [attr.aria-label]="'expense.form.line_items.unit_price' | translate"
              size="small"
            />
          </div>
          <p-button severity="danger" [text]="true" (onClick)="removeRow(i)" [ariaLabel]="'common.remove' | translate">
            <ng-template pTemplate="icon"><app-icon name="trash" [size]="14" /></ng-template>
          </p-button>
        </div>
      }
      <div>
        <p-button [label]="'expense.form.line_items.add' | translate" size="small" [outlined]="true" (onClick)="addRow()" />
      </div>
      <div class="line-items__total">
        <span>{{ 'expense.form.line_items.total' | translate }}:</span>
        <strong class="u-bidi">{{ total() | number: '1.2-2' }}</strong>
        {{ 'common.egp' | translate }}
      </div>
      @if (mismatch()) {
        <div class="line-items__warning" role="status">
          <svg width="14" height="14" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-alert-triangle" />
          </svg>
          {{ 'expense.form.line_items.mismatch' | translate }}
        </div>
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LineItemsEditorComponent {
  amount = input<number>(0);

  items = signal<LineItem[]>([{ description: '', quantity: 1, unit_price: 0 }]);
  itemsChange = output<LineItem[]>();

  total = computed(() =>
    this.items().reduce((sum, item) => sum + (item.quantity || 0) * (item.unit_price || 0), 0),
  );

  mismatch = computed(() => {
    const amount = this.amount();
    return amount > 0 && Math.abs(this.total() - amount) > 0.009;
  });

  addRow(): void {
    this.items.update((rows) => [...rows, { description: '', quantity: 1, unit_price: 0 }]);
    this.change();
  }

  removeRow(index: number): void {
    this.items.update((rows) => rows.filter((_, i) => i !== index));
    this.change();
  }

  preset(rows: LineItem[] | null): void {
    if (rows && rows.length) {
      this.items.set(rows.map((r) => ({ ...r })));
    }
  }

  change(): void {
    this.itemsChange.emit(this.items());
  }
}

import { ChangeDetectionStrategy, Component, computed, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { DialogModule } from 'primeng/dialog';
import { ButtonModule } from 'primeng/button';
import { TextareaModule } from 'primeng/textarea';
import type { HttpErrorResponse } from '@angular/common/http';
import type { ApiErrorBody } from '@shared/models/api.models';

/**
 * The shared reason/notes dialog (T3-02): every reject / cancel / resolve
 * action that the API requires a reason for goes through here — no action
 * ever sends hard-coded human text. The page receives the typed text via
 * `submit` and posts it under the field name its endpoint expects.
 */
@Component({
  selector: 'app-reason-dialog',
  standalone: true,
  imports: [TranslatePipe, DialogModule, ButtonModule, FormsModule, TextareaModule],
  template: `
    <p-dialog appendTo="body"
      [visible]="visible()"
      (visibleChange)="visible.set($event)"
      [header]="header() | translate"
      [modal]="true"
      [draggable]="false"
      [resizable]="false"
      styleClass="dialog"
      [breakpoints]="{ '576px': '100vw' }"
      [style]="{ width: 'min(480px, 94vw)' }"
      [closable]="!sending()"
    >
      <div class="field">
        <label class="field__label" for="reason-dialog-input">{{ label() | translate }} *</label>
        <textarea
          id="reason-dialog-input"
          pTextarea
          rows="3"
          [(ngModel)]="reason"
          name="reason"
          [maxlength]="maxLength()"
          style="width: 100%"
          (keydown.control.enter)="confirm()"
        ></textarea>
        @if (invalid()) {
          <p class="field__error">{{ 'validation.reason_min' | translate: { min: minLength() } }}</p>
        }
      </div>
      @if (alert()) {
        <div class="dialog__alert" role="alert">
          <svg width="16" height="16" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-alert-triangle" />
          </svg>
          <span>{{ alert() }}</span>
        </div>
      }
      <p-footer>
        <div class="u-flex u-gap-2" style="justify-content: flex-end">
          <p-button [label]="'common.cancel' | translate" severity="secondary" [text]="true" [disabled]="sending()" (onClick)="visible.set(false)" />
          <p-button [label]="submitLabel() | translate" [loading]="sending()" [disabled]="sending()" (onClick)="confirm()" />
        </div>
      </p-footer>
    </p-dialog>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ReasonDialogComponent {
  header = input.required<string>();
  label = input('common.reason');
  submitLabel = input('common.confirm');
  /** set while the caller's request is in flight */
  sending = input(false);
  /** a failed request — its message is shown inside the dialog */
  error = input<HttpErrorResponse | null>(null);
  minLength = input(3);
  maxLength = input(1000);

  submit = output<string>();

  visible = signal(false);
  reason = signal('');
  private tried = signal(false);

  invalid = computed(() => this.tried() && this.reason().trim().length < this.minLength());

  alert = computed(() => {
    const err = this.error();
    if (!err) {
      return null;
    }
    const body = err.error as ApiErrorBody | null;
    return body?.message ?? null;
  });

  open(): void {
    this.reason.set('');
    this.tried.set(false);
    this.visible.set(true);
  }

  done(): void {
    this.visible.set(false);
  }

  confirm(): void {
    this.tried.set(true);
    const value = this.reason().trim();
    if (value.length < this.minLength()) {
      return;
    }
    this.submit.emit(value);
  }
}

import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import type { RingSegment } from '@shared/ui/balance-ring/balance-ring.component';

const SERIES_COLORS = ['#5D3722', '#9E877A', '#4F2F1D', '#BEAFA7', '#7D5F4E', '#DFD7D3'];

/** Segmented bar sharing the ring's series order and colors (plan 10.1.4). */
@Component({
  selector: 'app-segmented-bar',
  standalone: true,
  imports: [TranslatePipe, MoneyPipe],
  template: `
    <div class="segmented-bar" role="img" [attr.aria-label]="aria()">
      @for (seg of widths(); track $index) {
        <span class="segmented-bar__segment" [style.width.%]="seg.width" [style.background]="seg.color"></span>
      }
    </div>
    <div class="segmented-bar__legend">
      @for (seg of segments(); track seg.label; let i = $index) {
        <span class="u-flex u-gap-1">
          <span class="u-visually-hidden"></span>
          <span style="width: 10px; height: 10px; border-radius: 2px; display: inline-block" [style.background]="color(i)"></span>
          {{ seg.label | translate }}: <strong class="u-bidi">{{ seg.amount | money }}</strong>
        </span>
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SegmentedBarComponent {
  segments = input.required<RingSegment[]>();

  widths = computed(() => {
    const total = this.segments().reduce((sum, s) => sum + (parseFloat(s.amount) || 0), 0);
    if (total <= 0) {
      return [];
    }
    return this.segments().map((s, i) => ({
      width: ((parseFloat(s.amount) || 0) / total) * 100,
      color: SERIES_COLORS[i % SERIES_COLORS.length],
    }));
  });

  color(index: number): string {
    return SERIES_COLORS[index % SERIES_COLORS.length];
  }

  aria(): string {
    return this.segments().map((s) => `${s.label}: ${s.amount}`).join(', ');
  }
}

import type {
  AfterViewInit,
  ElementRef} from '@angular/core';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  input,
  signal,
  viewChild,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import { MotionService } from '@core/motion/motion.service';

/**
 * Stat tile (plan 11.2): label, hero figure in the display face, companion
 * line. The figure counts up once per session view when motion allows (12.2).
 */
@Component({
  selector: 'app-stat-tile',
  standalone: true,
  imports: [TranslatePipe, MoneyPipe],
  template: `
    <div class="stat-tile" [class.stat-tile--wide]="wide()" [class.stat-tile--inset]="inset()">
      <span class="stat-tile__label">
        @if (icon()) {
          <ng-content select="[icon]" />
        }
        {{ label() | translate }}
      </span>
      @if (money()) {
        <span class="stat-tile__value" [class.stat-tile__value--hero]="hero()" #value
          >{{ displayValue() | money: false }}<span class="stat-tile__currency"> ج.م</span></span
        >
      } @else {
        <span class="stat-tile__value" [class.stat-tile__value--hero]="hero()">{{ displayValue() }}</span>
      }
      @if (caption()) {
        <span class="stat-tile__caption">{{ caption() | translate }}</span>
      }
      @if (hint()) {
        <span class="stat-tile__caption u-bidi">{{ hint() }}</span>
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class StatTileComponent implements AfterViewInit {
  label = input.required<string>();
  value = input<string | number>(0);
  money = input(false);
  hero = input(false);
  wide = input(false);
  inset = input(false);
  caption = input('');
  hint = input('');
  icon = input(false);

  private motion = inject(MotionService);
  private valueEl = viewChild<ElementRef<HTMLElement>>('value');
  private counted = signal(false);

  displayValue = computed(() => this.value());

  ngAfterViewInit(): void {
    if (!this.money() || this.counted()) {
      return;
    }
    const level = this.motion.level();
    const el = this.valueEl()?.nativeElement;
    if (!el) {
      return;
    }
    if (level === 'off' || level === 'lite' || !this.parse(this.value())) {
      return;
    }
    this.counted.set(true);
    this.countUp(el, this.parse(this.value())!);
  }

  private parse(v: string | number): number | null {
    const n = typeof v === 'string' ? parseFloat(v) : v;
    return isFinite(n) ? n : null;
  }

  /** 600ms one-shot count-up, GSAP-free (transform/opacity-only budget kept for elsewhere). */
  private countUp(el: HTMLElement, target: number): void {
    const start = performance.now();
    const dur = 600;
    const step = (now: number) => {
      const t = Math.min((now - start) / dur, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      el.textContent = (target * eased).toLocaleString('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
      if (t < 1) {
        requestAnimationFrame(step);
      }
    };
    requestAnimationFrame(step);
  }
}
